/// </summary>
[ExtensionOf(formDataFieldStr(InventLocation, InventLocation, AVAAutoShippingProcess))]
public final class AVAInventLocationFrm_InventLocationDS_AVAAutoShippingProcessFld_Extension
{
}

Method.Source:
/// <summary>
///  M.essl 11.03.2024
/// </summary>
public void modified()
{
    next modified();

    FormDataSource InventLocation_ds = element.dataSource(FormDataSourceStr(InventLocation,InventLocation));
    InventLocation InventLocationloc = InventLocation_ds.cursor();

    FormCheckBoxControl AVAAutoPackingSlipProcess = InventLocation_ds.formRun().design().controlName(formControlStr(InventLocation, AVAAutoPackingSlipProcess));
    FormCheckBoxControl AVAAutoBillofLoadingProcess = InventLocation_ds.formRun().design().controlName(formControlStr(InventLocation, AVAAutoBillofLoadingProcess));

    if (InventLocationloc.AVAAutoShippingProcess)
    {
        AVAAutoPackingSlipProcess.enabled(true);
        AVAAutoBillofLoadingProcess.enabled(true);
    }
    else
    {
        AVAAutoPackingSlipProcess.enabled(false);
        AVAAutoBillofLoadingProcess.enabled(false);
    }

}
